for k in list(a):
    m=re.fullmatch(r'(\d+) min read',k)
    if m:a[k]='阅读约 '+m[1]+' 分钟'
    if ' · ' in k and k.endswith(' min read'):
        topic, minutes=k.split(' · ');a[k]=a.get(topic,topic)+' · 阅读约 '+minutes.split()[0]+' 分钟'
    # Contextual terminology corrections for the remaining long-form translations.
    if len(k)>100:
        v=a[k]
        fixes={'路由':'线路','可充电重量':'计费重量','可充电重':'计费重','维重':'体积重','基电荷':'基础运费','国际海运押金':'国际运费预付款','国际运输押金':'国际运费预付款','最终充值':'最终费用','最后的充电':'最终费用','包裹引文':'包裹报价','直播订单':'当前订单','手动命令':'手动订单','购物代理流':'代购流程','自由存储':'免费仓储','1688年':'1688','纸浆':'包裹','大宗物项':'大件商品','化妆品细节':'外观细节'}
        for old,new in fixes.items():v=v.replace(old,new)
        if 'order' in k.lower():v=v.replace('命令','订单')
        if 'charge' in k.lower():v=v.replace('电荷','费用').replace('充电','收费')
        if 'listing' in k.lower():v=v.replace('上市','商品页面').replace('列名','商品信息')
        a[k]=v
